fn parser_peek_token_at(mut p: Rc<RefCell<Parser>>, offset: i64) -> Token {
    let idx = (p.borrow().pos + offset);
    if (idx < (p.borrow().tokens.len() as i64)) {
        p.borrow().tokens[(idx) as usize].clone()
    } else {
        Token { kind: TokenKind::Eof, line: 0 }
    }
}

