fn val_to_string(v: Value) -> Rc<str> {
    match v {
        Value::Nil => {
            Rc::<str>::from("nil")
        }
        Value::Void => {
            Rc::<str>::from("void")
        }
        Value::Uninitialized => {
            Rc::<str>::from("<uninitialized>")
        }
        Value::Bool(b) => {
            {
            if b {
                Rc::<str>::from("true")
            } else {
                Rc::<str>::from("false")
            }
}
        }
        Value::Int(n) => {
            int_to_string(n)
        }
        Value::Float(f) => {
            Rc::<str>::from(Rc::<str>::from(format!("{}", f).as_str()))
        }
        Value::Str(s) => {
            s.clone()
        }
        Value::Array(elems) => {
            let mut parts = vec![Rc::<str>::from("[")];
            let mut first = true;
            for e in elems.iter().cloned() {
                if (!first) {
                    parts.push(Rc::<str>::from(", "));
                }
                parts.push(val_to_string(e));
                first = false;
            }
            parts.push(Rc::<str>::from("]"));
            let mut result: Rc<str> = Rc::<str>::from("");
            for p in parts.iter().cloned() {
                result = Rc::<str>::from(Rc::<str>::from(format!("{}{}", result.as_ref(), p).as_str()));
            }
            result.clone()
        }
        Value::Tuple(elems) => {
            let mut parts = vec![Rc::<str>::from("(")];
            let mut first = true;
            for e in elems.iter().cloned() {
                if (!first) {
                    parts.push(Rc::<str>::from(", "));
                }
                parts.push(val_to_string(e));
                first = false;
            }
            parts.push(Rc::<str>::from(")"));
            let mut result: Rc<str> = Rc::<str>::from("");
            for p in parts.iter().cloned() {
                result = Rc::<str>::from(Rc::<str>::from(format!("{}{}", result.as_ref(), p).as_str()));
            }
            result.clone()
        }
        Value::Dict(pairs) => {
            let mut parts = vec![Rc::<str>::from("{")];
            let mut first = true;
            for pair in pairs.iter().cloned() {
                if (!first) {
                    parts.push(Rc::<str>::from(", "));
                }
                parts.push(val_to_string(pair.0));
                parts.push(Rc::<str>::from(": "));
                parts.push(val_to_string(pair.1));
                first = false;
            }
            parts.push(Rc::<str>::from("}"));
            let mut result: Rc<str> = Rc::<str>::from("");
            for p in parts.iter().cloned() {
                result = Rc::<str>::from(Rc::<str>::from(format!("{}{}", result.as_ref(), p).as_str()));
            }
            result.clone()
        }
        Value::Set(elems) => {
            let mut parts = vec![Rc::<str>::from("{")];
            let mut first = true;
            for e in elems.iter().cloned() {
                if (!first) {
                    parts.push(Rc::<str>::from(", "));
                }
                parts.push(val_to_string(e));
                first = false;
            }
            parts.push(Rc::<str>::from("}"));
            let mut result: Rc<str> = Rc::<str>::from("");
            for p in parts.iter().cloned() {
                result = Rc::<str>::from(Rc::<str>::from(format!("{}{}", result.as_ref(), p).as_str()));
            }
            result.clone()
        }
        Value::EnumVariant(typeName, variant, fields) => {
            if ((fields.len() as i64) == 0) {
                variant.clone()
            } else {
                let mut parts = vec![Rc::<str>::from(Rc::<str>::from(format!("{}(", variant).as_str()))];
                let mut first = true;
                for f in fields.iter().cloned() {
                    if (!first) {
                        parts.push(Rc::<str>::from(", "));
                    }
                    parts.push(val_to_string(f));
                    first = false;
                }
                parts.push(Rc::<str>::from(")"));
                let mut result: Rc<str> = Rc::<str>::from("");
                for p in parts.iter().cloned() {
                    result = Rc::<str>::from(Rc::<str>::from(format!("{}{}", result.as_ref(), p).as_str()));
                }
                result.clone()
            }
        }
        Value::NativeFn(name, _) => {
            Rc::<str>::from(Rc::<str>::from(format!("<fn {}>", name).as_str()))
        }
        Value::Fn(name, _) => {
            Rc::<str>::from(Rc::<str>::from(format!("<fn {}>", name).as_str()))
        }
        Value::OverloadedFn(name, _) => {
            Rc::<str>::from(Rc::<str>::from(format!("<overloaded fn {}>", name).as_str()))
        }
        Value::Closure(_, _, _) => {
            Rc::<str>::from("<closure>")
        }
        Value::Range(start, end, inclusive, _) => {
            if inclusive {
                Rc::<str>::from(Rc::<str>::from(format!("{}..{}", start, end).as_str()))
            } else {
                Rc::<str>::from(Rc::<str>::from(format!("{}..<{}", start, end).as_str()))
            }
        }
        Value::Labeled(label, val) => {
            let val = *val;
            Rc::<str>::from(Rc::<str>::from(format!("{}={}", label, val_to_string(val)).as_str()))
        }
        Value::Object(inner) => {
            Rc::<str>::from("<object>")
        }
        _ => {
            Rc::<str>::from("<value>")
        }
    }
}

fn val_to_bool(v: Value) -> bool {
    match v {
        Value::Nil => {
            false
        }
        Value::Void => {
            false
        }
        Value::Uninitialized => {
            false
        }
        Value::Bool(b) => {
            b
        }
        Value::Int(n) => {
            (n != 0)
        }
        Value::Float(f) => {
            (f != 0.0)
        }
        Value::Str(s) => {
            (s != Rc::<str>::from(""))
        }
        Value::Array(elems) => {
            ((elems.len() as i64) != 0)
        }
        Value::Dict(pairs) => {
            ((pairs.len() as i64) != 0)
        }
        Value::Set(elems) => {
            ((elems.len() as i64) != 0)
        }
        Value::Tuple(elems) => {
            ((elems.len() as i64) != 0)
        }
        _ => {
            true
        }
    }
}

fn values_equal(a: Value, b: Value) -> bool {
    match a {
        Value::Nil => {
            match b {
                Value::Nil => {
                    true
                }
                _ => {
                    false
                }
            }
        }
        Value::Void => {
            match b {
                Value::Void => {
                    true
                }
                _ => {
                    false
                }
            }
        }
        Value::Bool(x) => {
            match b {
                Value::Bool(y) => {
                    (x == y)
                }
                _ => {
                    false
                }
            }
        }
        Value::Int(x) => {
            match b {
                Value::Int(y) => {
                    (x == y)
                }
                Value::Float(y) => {
                    ((x as f64) == y)
                }
                _ => {
                    false
                }
            }
        }
        Value::Float(x) => {
            match b {
                Value::Float(y) => {
                    (x == y)
                }
                Value::Int(y) => {
                    (x == (y as f64))
                }
                _ => {
                    false
                }
            }
        }
        Value::Str(x) => {
            match b {
                Value::Str(y) => {
                    (x == y)
                }
                _ => {
                    false
                }
            }
        }
        Value::Array(xs) => {
            match b {
                Value::Array(ys) => {
                    if ((xs.len() as i64) != (ys.len() as i64)) {
                        false
                    } else {
                        let mut i = 0;
                        let mut eq = true;
                        while (i < (xs.len() as i64)) {
                            if (!values_equal(xs[(i) as usize].clone(), ys[(i) as usize].clone())) {
                                eq = false;
                            }
                            i += 1;
                        }
                        eq
                    }
                }
                _ => {
                    false
                }
            }
        }
        Value::Tuple(xs) => {
            match b {
                Value::Tuple(ys) => {
                    if ((xs.len() as i64) != (ys.len() as i64)) {
                        false
                    } else {
                        let mut i = 0;
                        let mut eq = true;
                        while (i < (xs.len() as i64)) {
                            if (!values_equal(xs[(i) as usize].clone(), ys[(i) as usize].clone())) {
                                eq = false;
                            }
                            i += 1;
                        }
                        eq
                    }
                }
                _ => {
                    false
                }
            }
        }
        Value::EnumVariant(tn1, v1, f1) => {
            match b {
                Value::EnumVariant(tn2, v2, f2) => {
                    if (((tn1 != tn2) || (v1 != v2)) || ((f1.len() as i64) != (f2.len() as i64))) {
                        false
                    } else {
                        let mut i = 0;
                        let mut eq = true;
                        while (i < (f1.len() as i64)) {
                            if (!values_equal(f1[(i) as usize].clone(), f2[(i) as usize].clone())) {
                                eq = false;
                            }
                            i += 1;
                        }
                        eq
                    }
                }
                _ => {
                    false
                }
            }
        }
        Value::Range(s1, e1, inc1, _) => {
            match b {
                Value::Range(s2, e2, inc2, _) => {
                    (((s1 == s2) && (e1 == e2)) && (inc1 == inc2))
                }
                _ => {
                    false
                }
            }
        }
        _ => {
            false
        }
    }
}

